window.STORY_CHAPTERS["ccd1729e07eed0800"]={"id":"ccd1729e07eed0800","lines":[{"uid":"talk.vc.home_day_administrator_uw_sleeping_4#originalText","id":"talk.vc.home_day_administrator_uw_sleeping_4","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"一不小心就让你休息太久了呢。明天开始你要努力运行任务。","en":"I let you overindulge in your rest today. Be sure to work extra hard for me starting tomorrow.","ja":"あなたにはずいぶん休息を与えてしまったわね明日からは任務に邁進なさい"},"kind":"dialogue"},{"uid":"talk.vc.home_event_administrator_uw_sleeping_1#originalText","id":"talk.vc.home_event_administrator_uw_sleeping_1","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"新的一年又开始了呢。和前一年相同的一年……然后，明年也依旧是如此。","en":"A new year is upon us. It shall be no different from the year before it...or the year after.","ja":"また、新しい年が始まったのね前の年と変わらない一年……そして、来年もまた同じよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_administrator_uw_sleeping_2#originalText","id":"talk.vc.home_event_administrator_uw_sleeping_2","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"如果撒豆子就能赶跑黑暗界的人马，那我就不用如此劳心伤神了。","en":"I wish throwing beans could drive away the Dark Realm's forces. That would certainly be easier.","ja":"豆をまく程度で暗黒界の輩を追い返せるなら私も苦労せずにすむのだけれど"},"kind":"dialogue"},{"uid":"talk.vc.home_event_administrator_uw_sleeping_3#originalText","id":"talk.vc.home_event_administrator_uw_sleeping_3","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"我只会在必要之时赐予你奖励，奢求过多当心自取灭亡喔。","en":"I shall give you a gift only when you deserve one. Greed will destroy you.","ja":"あなたに何かをあげるのはその必要がある時だけ望みすぎると破滅するわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_administrator_uw_sleeping_4#originalText","id":"talk.vc.home_event_administrator_uw_sleeping_4","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"祝贺孩童的成长……是一件好事。受到祝福的孩子也会成长，留下子孙，接着衰老……回归天上。","en":"Children... Worthy of celebration. They shall bear more children, age, then die and return to the heavens.","ja":"子の成長を祝う……いいことねそしてその子どもは、成長して自らも子を産み、老いて……天に帰るの"},"kind":"dialogue"},{"uid":"talk.vc.home_event_administrator_uw_sleeping_5#originalText","id":"talk.vc.home_event_administrator_uw_sleeping_5","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"要献给我的东西？这样啊，你就放在那吧。我想到就会去瞧瞧的。","en":"A gift for me? Well, set it down. I shall have a look at it later, if the mood strikes me.","ja":"私への捧げ物?そうね、そこへ置いておいて気が向いたら見てあげるから"},"kind":"dialogue"},{"uid":"talk.vc.home_event_administrator_uw_sleeping_6#originalText","id":"talk.vc.home_event_administrator_uw_sleeping_6","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"竟然有允许欺瞒他人的日子，对面真是可怕的地方，跟这里一样……不，比这里还要糟。","en":"A day where deceit is forgiven? The outside world certainly is horrible. More so than here.","ja":"人を騙しても許される日、なんて向こう側はおぞましいところねここと同じ……いえ、それ以上に"},"kind":"dialogue"},{"uid":"talk.vc.home_event_administrator_uw_sleeping_7#originalText","id":"talk.vc.home_event_administrator_uw_sleeping_7","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"漫长的安息常使人心过于亢奋。可以的话，真想让这种风俗消失。","en":"If a person rests for too long, their mind might rot. I wish we could abolish such a holiday.","ja":"長い安息は、人の心を必要以上に沸き立たせてしまうのできれば、なくしたい風習ね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_administrator_uw_sleeping_8#originalText","id":"talk.vc.home_event_administrator_uw_sleeping_8","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"降雨要是持续太久，那我就得考虑操控天候了，毕竟让人民挨饿也不好。","en":"If the rains continue for too long, we must manipulate the weather. The people mustn't starve.","ja":"あまりにも長雨が続くなら天候操作も考えないと民が飢えすぎるのもよくないわ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_administrator_uw_sleeping_9#originalText","id":"talk.vc.home_event_administrator_uw_sleeping_9","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"就算是我，要做出银河也不是那么容易的。不过，这是以现阶段而言。","en":"Not even I am capable of creating a river of stars. At my current level, that is.","ja":"私でも、星の川を作り出すことはちょっと無理ね今の段階では、だけれど"},"kind":"dialogue"},{"uid":"talk.vc.home_event_administrator_uw_sleeping_10#originalText","id":"talk.vc.home_event_administrator_uw_sleeping_10","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"夏至祭典的声响连这里都听得见。我明白人民需要娱乐，但这还是让我觉得心烦。","en":"I understand that the people need their fun, but the racket of this Summer Festival is most annoying.","ja":"夏至祭の音がここまで聞こえる民にも楽しみが必要なのはわかるけど、煩わしいわ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_administrator_uw_sleeping_11#originalText","id":"talk.vc.home_event_administrator_uw_sleeping_11","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"早安，漫漫长眠还睡得安稳吗？从今天开始，再次为我服务吧。","en":"Good morning. Did you enjoy your long slumber? Good. Now, get back to serving me.","ja":"おはよう。長い眠りはどうだった?今日からまた、私のために働いてちょうだい"},"kind":"dialogue"},{"uid":"talk.vc.home_event_administrator_uw_sleeping_12#originalText","id":"talk.vc.home_event_administrator_uw_sleeping_12","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"露那利亚的光芒与索鲁斯不同，真是舒服。","en":"I vastly prefer Lunaria's light over Solus. It is so much more soothing.","ja":"ルナリアの光は、ソルスと違って心地いいわね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_administrator_uw_sleeping_13#originalText","id":"talk.vc.home_event_administrator_uw_sleeping_13","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"哦，Trick or Treat啊……那么「调整」跟「施舍」，你想要哪个呢？","en":"\"Trick or Treat\"... Interesting. Would you rather I \"trick\" your memories, or \"treat\" your soul?","ja":"へえ、トリックオアトリート……ねなら、あなたは「調整」と「施し」どちらを望むのかしら"},"kind":"dialogue"},{"uid":"talk.vc.home_event_administrator_uw_sleeping_15#originalText","id":"talk.vc.home_event_administrator_uw_sleeping_15","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"我喜欢眺望雪景。因为那就像是我的心整理完记忆之后的样子。","en":"I do love a snowy landscape. It resembles my soul after I've arranged my memories.","ja":"雪景色を見るのは好きよまるで記憶を整理した後の私の心みたいだから"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_administrator_uw_sleeping_3#originalText","id":"talk.vc.home_bd_administrator_uw_sleeping_3","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"那个小子出生的日子……他本身是个不错的材料，真希望可以从小就对他进行调整。","en":"The day that boy was born... If I could, I would love to return his memory to his younger days.","ja":"あの坊やが生まれた日……素材はいいから、できれば幼い頃に調整を施したかったわ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_administrator_uw_sleeping_4#originalText","id":"talk.vc.home_bd_administrator_uw_sleeping_4","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"要是时间允许，我想把我的爱赠予尤吉欧，让他忘却一切。","en":"If time permitted, I would gift Eugeo my love to help him forget everything.","ja":"時間さえ許せば、ユージオには私の愛を贈って、すべてを忘れさせてあげたいわね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_administrator_uw_sleeping_5#originalText","id":"talk.vc.home_bd_administrator_uw_sleeping_5","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"今天是爱丽丝小妹妹的生日？这样的话，把那两个小子当「礼物」送她，她应该会很开心吧。","en":"Is it little Alice's birthday? Do you suppose she would like those two boys as a \"gift\"?","ja":"アリスちゃんの誕生日なの?なら、あの坊やふたりを「贈り物」にしたら、喜ぶかしらね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_administrator_uw_sleeping_1#originalText","id":"talk.vc.home_etc_administrator_uw_sleeping_1","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"工作做完了？那就快点向我回报，回报完才会有奖赏。","en":"Have you finished your task? Then report to me at once. Your reward will come later.","ja":"仕事は終わったの?なら、速やかに報告なさい褒美はその後よ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_administrator_uw_sleeping_2#originalText","id":"talk.vc.home_etc_administrator_uw_sleeping_2","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"哎呀，那个盒子是什么？是有人送你的吗？希望你还能记得对方是谁呢。","en":"Oh, what is inside that box? Who gave it to you? I hope you can remember.","ja":"あら、その箱はなに?誰かからもらったのかしらその相手を覚えているといいけど"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_administrator_uw_sleeping_3#originalText","id":"talk.vc.home_etc_administrator_uw_sleeping_3","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"好了，去运行任务吧。要是表现得好，我还会在这里继续爱你。","en":"Now, embark on your mission. If you are successful, I shall reward you with more love.","ja":"さあ、任務に行きなさい首尾良く終えてくればまたここで愛してあげるわ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_administrator_uw_sleeping_1#originalText","id":"talk.vc.home_season_administrator_uw_sleeping_1","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"每到春天，就会有许多集成骑士变得不稳定，你没问题吧？","en":"Springtime always makes me uneasy. There are too many Integrity Knights. Are you all right?","ja":"春になると、不安定になる整合騎士は多いのよあなたは大丈夫かしら?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_administrator_uw_sleeping_2#originalText","id":"talk.vc.home_season_administrator_uw_sleeping_2","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"和我保持一点距离。今天的气温很高，你靠得太近我会热。","en":"Stay back a little. It is far too hot to be close to you today.","ja":"少し離れなさい今日は気温が高いから側にいられると暑いの"},"kind":"dialogue"},{"uid":"talk.vc.home_season_administrator_uw_sleeping_3#originalText","id":"talk.vc.home_season_administrator_uw_sleeping_3","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"外面好像在刮风下雨呢。让我们听着这阵风啸声小歇片刻吧。","en":"A storm is coming. Let us nap to the song of the wind.","ja":"外は嵐が来ているようねこの風の音を聞きながらまどろみましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_season_administrator_uw_sleeping_4#originalText","id":"talk.vc.home_season_administrator_uw_sleeping_4","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"你在发抖呢，真是可怜。别担心，只有我才能给你温暖。","en":"Oh, you poor thing. You're shivering. Fear not. I shall keep you warm.","ja":"震えているのね、可哀想に大丈夫、私だけはあなたを温めてあげられる"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_uw_2nd_anniv_1#originalText","id":"talk.vc.home_wait_edith_uw_2nd_anniv_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"イーディス"},"text":{"cn":"果然没错，看到妳的脸，我就会充满活力。要是腻在一起，就会更有活力了！","en":"Ooh, I knew seeing you would cheer me up. Come closer if you want to cheer me up even more!","ja":"やっぱり、あなたの顔を見ると元気が出てくるわくっつけば、もっと元気になるの!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_uw_2nd_anniv_2#originalText","id":"talk.vc.home_wait_edith_uw_2nd_anniv_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"イーディス"},"text":{"cn":"集成骑士从来没有聚在一起玩过对吧？下次邀请大家一起吃顿饭好了。","en":"Y'know, the Integrity Knights never got together to hang out before. How about we all have dinner later?","ja":"整合騎士みんなで遊んだことって今までなかったわよね今度みんなでご飯でも食べようか"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_uw_2nd_anniv_3#originalText","id":"talk.vc.home_wait_edith_uw_2nd_anniv_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"イーディス"},"text":{"cn":"很久没练剑了，我今天要来训练一下。我可不能输给妳呢，因为我是姊姊啊。","en":"I'm gonna go back to my sword training today—can't let you outshine me, can I? I'm the big sister, see.","ja":"今日は久しぶりに剣の稽古をするのあなたに負けてられないからねあたしはお姉ちゃんなんだから"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_uw_2nd_anniv_4#originalText","id":"talk.vc.home_wait_edith_uw_2nd_anniv_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"上级司祭他们给人感觉很差呢。虽然阿优哈和索妮丝很可爱。","en":"I dunno, I'm just not a big fan of the senior priests. Though Ayuha and Soness are pretty cute.","ja":"上級司祭たちって、なんかいけ好かないのよねアユハとソネスは可愛いけど"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_uw_2nd_anniv_5#originalText","id":"talk.vc.home_wait_edith_uw_2nd_anniv_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天要小心元老长，因为最高司祭大人休假的关系，他现在相当暴躁喔。","en":"Steer clear of the Prime Senator today. He's really upset because the High Pontifex is resting all day.","ja":"今日の元老長には気をつけて最高司祭様がお休み中だからかなりイライラしているわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_uw_2nd_anniv_6#originalText","id":"talk.vc.home_wait_edith_uw_2nd_anniv_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天没有任何预定，我们就两个人好好放松吧。要不要去空中庭园散步？","en":"Since we've both got nothing to do, let's spend the day together! Hm... How about a walk in the sky garden?","ja":"今日は何もない日だからふたりでゆっくりしましょう空中庭園をお散歩とか、どう?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_uw_2nd_anniv_7#originalText","id":"talk.vc.home_wait_edith_uw_2nd_anniv_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"欸，妳什么时候才愿意叫我「姊姊」啊？我的心门随时都对妳敞开喔！","en":"So, when're you gonna finally start calling me \"big sister\"? My ears are always ready.","ja":"ねえ、いつになったらあたしのこと「お姉ちゃん」って呼んでくれるの?いつでも大歓迎だよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_uw_2nd_anniv_8#originalText","id":"talk.vc.home_wait_edith_uw_2nd_anniv_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"在尽头之壁的另一端是不是也住着人，有着城堡，街上车水马龙呢？","en":"I wonder if there's a castle and cities full of people on the other side of the Wall at the End of the World?","ja":"終わりの壁の向こうにも人がいて、お城もあって街が賑わったりしているのかな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_uw_2nd_anniv_9#originalText","id":"talk.vc.home_wait_edith_uw_2nd_anniv_9","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"……呵呵，妳这样注视远方的侧脸，也非常动人呢。让我好想一直看下去。","en":"Aww, you're so pretty when you stare off into the distance like that. I could gaze at you for hours.","ja":"……ふふ、そうやって遠くを見ているあなたの横顔も、とっても素敵だないつまでも見ていたくなるの"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_uw_2nd_anniv_1#originalText","id":"talk.vc.home_touch_edith_uw_2nd_anniv_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我自己也很喜欢这个发色。不过，妳那头漂亮的金发也让人有点向往呢。","en":"I love my hair color, if I do say so myself. But I kinda also wish I had your pretty golden locks.","ja":"この髪の色、自分でも気に入ってるのでも、あなたみたいな綺麗な金髪もちょっと憧れちゃうな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_uw_2nd_anniv_2#originalText","id":"talk.vc.home_touch_edith_uw_2nd_anniv_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"欸，再使劲点把我的头发弄乱吧。妳这么做，我觉得还挺舒服的呢。","en":"Hey, could you tussle my hair even harder? I actually kinda like how that feels.","ja":"ね、もっと思いっきり髪をグシャグシャってしてみてそうされるのもちょっと気持ちいいの"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_uw_2nd_anniv_3#originalText","id":"talk.vc.home_touch_edith_uw_2nd_anniv_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"喂、喂……我的耳朵也是会痒的好吗！真是的……越来越不好对付了呢。","en":"W-Whoa, there...I have ticklish spots too, you know. Geesh...your hands've gotten awfully strong.","ja":"ちょ、ちょっと……あたしだって耳はくすぐったいよもう……手強くなったわね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_uw_2nd_anniv_4#originalText","id":"talk.vc.home_touch_edith_uw_2nd_anniv_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"爱恶作剧的手……可恶，看我抓起来！只要逮到了，我就不会再放开了喔！","en":"Why, you naughty little hands... Gotcha! Now you're mine!","ja":"そういうイタズラな手は……えいっ、捕まえちゃうぞ!捕まえたら、離さないからね!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_uw_2nd_anniv_5#originalText","id":"talk.vc.home_touch_edith_uw_2nd_anniv_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"不用摸得那么提心吊胆啦，妳的话我是不会生气的。","en":"Come on, you don't have to be shy. If it's you, I won't get bad.","ja":"そんな、おっかなびっくり触らなくても、あなただったら怒ったりしないわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_uw_2nd_anniv_6#originalText","id":"talk.vc.home_touch_edith_uw_2nd_anniv_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我讨厌穿着衣服，紧贴着肌肤的触感让我烦躁难耐……","en":"I just hate wearing clothes! The cloth is so rough against my skin.","ja":"綺麗な指ね……細くてしなやかで、柔らかくてね、もっとよく見せて"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_uw_2nd_anniv_7#originalText","id":"talk.vc.home_touch_edith_uw_2nd_anniv_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"妳最近是不是比较爱撒娇？呵呵，这样的妳也很可爱哦，让人想多宠妳一下呢。","en":"Is it just me or have you gotten really needy lately? Hehe, well you're so adorable I just have to dote on you.","ja":"最近ちょっと甘えん坊さんになった?ふふ、そんなあなたも可愛いわもっと甘やかしたくなっちゃう"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_uw_2nd_anniv_8#originalText","id":"talk.vc.home_touch_edith_uw_2nd_anniv_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"像这样碰触彼此，让我清楚感受到妳就在身边。所谓的幸福，就是这么回事吧。","en":"When we touch each other like this, I feel so close to you. This must be what true happiness is.","ja":"こうやって触れあってるとあなたが近くにいるって感じるわ幸せって、こういうことを言うのね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_uw_2nd_anniv_1#originalText","id":"talk.vc.home_time_edith_uw_2nd_anniv_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"早安。一早就见到妳，感觉今天一整天都能过得很快乐呢！","en":"Good morning! Seeing you first thing in the morning means this's gonna be a great day!","ja":"おはよう朝からあなたに会えて今日は一日楽しく過ごせそう!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_uw_2nd_anniv_2#originalText","id":"talk.vc.home_time_edith_uw_2nd_anniv_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"清晨的空气真是舒服呢。和妳待在一块，感觉更加清新了。","en":"I sure love the smell of mornings. And I feel extra refreshed when I'm with you.","ja":"朝の空気っていいわよねあなたが一緒だとよりいっそう爽やかな気がするわ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_uw_2nd_anniv_3#originalText","id":"talk.vc.home_time_edith_uw_2nd_anniv_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天好困喔……欸，要不要一起睡回笼觉？一定会很舒服的喔～","en":"I'm so sleepy today... Hey, wanna just go back to bed? Come on. It'll feel really nice.","ja":"今日は眠いわね……ねえ、ふたりで二度寝しない?きっと気持ちいいわよ～"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_uw_2nd_anniv_4#originalText","id":"talk.vc.home_time_edith_uw_2nd_anniv_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我今天想和雾舞一起吃午餐。妳方便的话要不要也加入我们呢？","en":"I was gonna go out to lunch with Kirimai today. Want to join us?","ja":"今日は、霧舞と一緒にお昼を食べようと思うんだよかったら、あなたもどう?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_uw_2nd_anniv_5#originalText","id":"talk.vc.home_time_edith_uw_2nd_anniv_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"偶尔也得练习术式才行呢。不然就算记得，真要用时却念不好发音也没用。","en":"I should really try to keep up with my Sacred Arts. Wouldn't want to forget an incantation when I really need it.","ja":"たまには術式の勉強もしないとね覚えていても、いざという時ちゃんと発音できないと困っちゃうし"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_uw_2nd_anniv_6#originalText","id":"talk.vc.home_time_edith_uw_2nd_anniv_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"好～今天的工作结束！比我原本预期的还要快呢，索鲁斯竟然还高高挂在天上。","en":"Yay, I'm done with work for the day! Went faster than I thought it would. Just look how high Solus still is!","ja":"よーし、今日のお仕事終わり!思ったより早く終わったわまだ、こんなにソルスが高いなんて"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_uw_2nd_anniv_7#originalText","id":"talk.vc.home_time_edith_uw_2nd_anniv_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"呜呜，今天被骑士长抢先，第一个进去浴池了……那个人也非常喜欢泡澡呢。","en":"Uh-oh, the Commander snatched the first bath right from me! That man loves his baths, too, doesn't he?","ja":"うう、今日は騎士長に一番風呂取られちゃった……あの人も、かなりお風呂好きだよね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_uw_2nd_anniv_8#originalText","id":"talk.vc.home_time_edith_uw_2nd_anniv_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"像这样静静待在黑暗中，就会感觉自己也融入黑暗，混为一体。","en":"Lying still in the darkness likes this makes me feel like I'm melting into it.","ja":"こうやって闇の中で静かにしてると自分も闇に溶けて混ざっちゃうようなそんな気がしてくるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_uw_2nd_anniv_9#originalText","id":"talk.vc.home_time_edith_uw_2nd_anniv_9","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天也辛苦妳了。好好洗个澡来养足明天的精神吧。当然是跟我一起！","en":"Another day in the books! Let's take a nice soothing bath to recharge. Together, of course!","ja":"今日もお疲れさま明日に備えて、ゆっくりお風呂に入りましょう。もちろん、一緒に!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_uw_2nd_anniv_10#originalText","id":"talk.vc.home_time_edith_uw_2nd_anniv_10","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"睡不着的时候，不用勉强自己去睡没关系。我想这种思考的时间，对妳而言也是不可或缺的。","en":"If you can't sleep, don't force it. Your brain must've needed this time to think.","ja":"眠れない時は、無理に寝なくていいのよ。そうやって考える時間もきっとあなたに必要な時間なの"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_uw_2nd_anniv_11#originalText","id":"talk.vc.home_time_edith_uw_2nd_anniv_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"啊，抱歉，吵醒妳了吗？我有点睡不着，所以想去散散步。","en":"Oops, did I wake you? Sorry, I couldn't sleep. I was about to go on a walk.","ja":"あ、ごめん。起こしちゃった?ちょっと眠れなくてねお散歩しようと思ってたの"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_uw_2nd_anniv_12#originalText","id":"talk.vc.home_time_edith_uw_2nd_anniv_12","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这么晚了还在运行任务？妳一定累了吧，我热杯牛奶给妳喝。","en":"Wow, you were out this late on duty? You must be exhausted. I'll go get you some warm milk.","ja":"こんな時間まで任務だったの?疲れたでしょう、温かいミルクを作ってあげるね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_uw_2nd_anniv_1#originalText","id":"talk.vc.home_day_edith_uw_2nd_anniv_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天开始又得好好加油才行。这样到了下个安息日，肯定又会是快乐的一天。","en":"Aw, I have to go back to work today. But I know our next day of rest will be just as fun as the last.","ja":"今日からまた頑張らないとねそうしたら、きっと次の安息日も楽しい日になるわ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_uw_2nd_anniv_2#originalText","id":"talk.vc.home_day_edith_uw_2nd_anniv_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这周的任务好像很累人呢。妳别太勉强自己，要记得时不时让身体休息才行。","en":"I hear you've got a busy week ahead. Don't kill yourself, okay? Get plenty of rest.","ja":"今週は、任務が大変みたいねあんまり無理しないで、時々は体を休めないとね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_uw_2nd_anniv_3#originalText","id":"talk.vc.home_day_edith_uw_2nd_anniv_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"假日决定好要做什么了吗？妳方便的话，要不要找个地方跟我一起去玩？","en":"Any plans for your day off? Want to go somewhere with me?","ja":"お休みの予定は決まってる?よかったら、あたしと一緒にどこか遊びに行かない?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_uw_2nd_anniv_4#originalText","id":"talk.vc.home_day_edith_uw_2nd_anniv_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"安息日过得开心吗？如果我有跟妳一起过，一定会很满足的。","en":"Did you enjoy the day of rest? Since I got to be with you, I had the best day ever, of course.","ja":"安息日は楽しかった?あたしは、あなたと一緒だったから大満足だったわ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_uw_2nd_anniv_1#originalText","id":"talk.vc.home_event_edith_uw_2nd_anniv_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"新年快乐。妳今年有确实看到新年最初的索鲁斯大人吗？","en":"Happy New Year! Did you get to see Solus' first rise this time?","ja":"あけましておめでとう新年最初のソルス様今年はちゃんと見られた?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_uw_2nd_anniv_2#originalText","id":"talk.vc.home_event_edith_uw_2nd_anniv_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"Generate metallic element！Bean's shape！这样就能彻底击退恶鬼了！","en":"Generate Metallic Element! Bean Shape! Now we can totally ward off all the demons!","ja":"ジェネレート・メタリック・エレメント! ビーンズシェイプ!これで悪鬼も完璧に退治できるわ!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_uw_2nd_anniv_3#originalText","id":"talk.vc.home_event_edith_uw_2nd_anniv_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今年要不要一起做点心，然后再彼此交换着吃？我觉得一定会很有趣喔。","en":"Hey, wanna make and exchange chocolates together this year? I think it'll be fun!","ja":"今年は、一緒にお菓子を作ってお互いに交換しない?きっと楽しいと思うの"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_uw_2nd_anniv_4#originalText","id":"talk.vc.home_event_edith_uw_2nd_anniv_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我一开始还以为女儿节的「雏人偶」是指飞龙幼雏的玩偶，原来幼小的人类也称为「雏」啊。","en":"When I first heard Hinamatsuri was a day for \"chicks,\" I thought they meant \"dragon chicks\"...but it's \"girls\"!","ja":"ひな人形って、最初は飛竜の雛の人形かと思ったの人間も雛って呼ばれるのね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_uw_2nd_anniv_5#originalText","id":"talk.vc.home_event_edith_uw_2nd_anniv_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"不只有送礼的习俗，连回礼的习俗都有，感觉真的很棒呢。","en":"Wow, don't you just love how they have not only a gift-giving, but a thank you gift-giving holiday, too?","ja":"贈る風習だけじゃなくてお返しの風習もあるってなんだか素敵だよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_uw_2nd_anniv_6#originalText","id":"talk.vc.home_event_edith_uw_2nd_anniv_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"说谎原本是不对的事，但听到「说谎也没关系」时，我就想去捉弄元老长呢。","en":"I know lying is wrong, but when I'm given a pass, I suddenly have the urge to prank the Prime Senator.","ja":"本当は嘘ついちゃいけないけど「ついてもいい」って言われたら元老長をからかいたくなるわね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_uw_2nd_anniv_7#originalText","id":"talk.vc.home_event_edith_uw_2nd_anniv_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我排到了一个长假，跟我一起出远门吧。坐上飞龙飞到远一点的地方，怎么样？","en":"I got a few days off, so let's travel somewhere together! How about a nice long dragon ride?","ja":"長い休暇がもらえたから一緒にお出かけしましょうよ飛竜で遠乗りとか、どう?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_uw_2nd_anniv_8#originalText","id":"talk.vc.home_event_edith_uw_2nd_anniv_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我不讨厌下雨，但我不喜欢这种潮湿的空气，会让我想把衣服脱掉。","en":"I don't hate the rain, but I could do without the humidity. Makes me wanna take off all my clothes.","ja":"雨は嫌いじゃないけどジメジメした空気は苦手服を脱ぎ捨てたくなっちゃう"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_uw_2nd_anniv_9#originalText","id":"talk.vc.home_event_edith_uw_2nd_anniv_9","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我一定会等妳回来。所以，就算妳去了远方，也绝对别忘了我喔。","en":"I would wait for you always, even if you went far away from me. I know I would never forget you.","ja":"あたしは必ずあなたを待ってるだから、もし遠くに行っちゃってもきっとあたしを忘れないでね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_uw_2nd_anniv_10#originalText","id":"talk.vc.home_event_edith_uw_2nd_anniv_10","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天一起去游泳吧。妳看，妳的泳装我也准备好了喔！","en":"Let's go for a swim today! I made sure to get you a swimsuit, too! See?","ja":"今日は一緒に泳ぎに行きましょうほら、あなたの水着もちゃーんと用意してあるんだから!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_uw_2nd_anniv_11#originalText","id":"talk.vc.home_event_edith_uw_2nd_anniv_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"夏天的假期就到今天而已。不过我一点也不寂寞，因为秋天也能继续跟妳在一起。","en":"Our summer vacation may be over, but I'm not sad. I mean, I still get to see you in the fall!","ja":"夏の休暇は今日で終わりでも寂しくはないわね秋も、あなたと一緒にいられるから"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_uw_2nd_anniv_12#originalText","id":"talk.vc.home_event_edith_uw_2nd_anniv_12","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"用团子供奉月亮，真是有趣的习俗呢。露那利亚大人喜欢吃团子吗？","en":"Feeding the moon snacks is a funny custom, don't you think? Does Lunaria like cake?","ja":"ルナリア様にお団子をお供えするってなんだか面白い風習ねルナリア様はお団子が好きなの?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_uw_2nd_anniv_13#originalText","id":"talk.vc.home_event_edith_uw_2nd_anniv_13","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"有变装的人跑进圣堂里了！结果我定睛一看发现是元老长。","en":"Look! There's a costumed person coming into the Cathedral! Oops, It's just the Prime Senator.","ja":"カセドラルの中に仮装した人が入ってきてる!って思ったら元老長だったの"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_uw_2nd_anniv_15#originalText","id":"talk.vc.home_event_edith_uw_2nd_anniv_15","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天是飞天的集成骑士大叔送礼物给大家的日子喔。","en":"Today's the special day when the Integrity Knight in red flies in on his dragon sleigh to give us presents!","ja":"今日は空飛ぶ整合騎士のおじさんが贈り物を持って来る日よ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_edith_uw_2nd_anniv_1#originalText","id":"talk.vc.home_season_edith_uw_2nd_anniv_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"天气越来越暖和了呢。冬天过后，雾舞牠们也耐不住性子想赶快翱翔了。","en":"Gee, it's sure gotten warm. Now that winter's gone, Kirimai and her siblings are itching to fly.","ja":"暖かくなってきたね冬を終えて、霧舞たちも飛びたくてうずうずしてるわ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_edith_uw_2nd_anniv_2#originalText","id":"talk.vc.home_season_edith_uw_2nd_anniv_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"食物在夏天一下就耗尽天命了……前阵子那个难得的派也是，唉……","en":"Aw, why does food go bad so quickly in the summer? The pie I just bought is ruined...","ja":"夏は、食べ物の天命がすぐに尽きちゃうから……この前もせっかくのパイが、ああ……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_edith_uw_2nd_anniv_3#originalText","id":"talk.vc.home_season_edith_uw_2nd_anniv_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"听说今年作物大丰收，这也是因为提拉利亚大人庇佑呢。得谢谢祂才行。","en":"The farmers had a great harvest this year. And we have Terraria's generosity to thank!","ja":"今年は作物が豊作なんだってこれもテラリア様のご加護ね感謝しないと"},"kind":"dialogue"},{"uid":"talk.vc.home_season_edith_uw_2nd_anniv_4#originalText","id":"talk.vc.home_season_edith_uw_2nd_anniv_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我才觉得冷就下起雪来了。妳不觉得在浴池里赏雪，是一种极致奢侈的享受吗？","en":"No wonder it's cold... It's snowing! Hey, wouldn't it be nice to take a bath while watching the snow fall?","ja":"寒いと思ったら雪が降ってきたわお風呂の中で雪を見るのって最高の贅沢だと思わない?"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_uw_2nd_anniv_2#originalText","id":"talk.vc.home_bd_edith_uw_2nd_anniv_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我的生日……老实说我感受不到有什么特别的，但我很高兴妳为我祝福。","en":"My birthday...? Sure doesn't feel like it. But I appreciate the gesture.","ja":"あたしの誕生日……実感は正直ないんだけどお祝いしてくれるのはうれしいわ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_uw_2nd_anniv_3#originalText","id":"talk.vc.home_bd_edith_uw_2nd_anniv_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"桐人的生日到了，机会难得，我们一起为他庆祝吧，盛大地祝贺他一番！","en":"It's Kirito's birthday today. Hey, let's throw him a party. A BIIIG party!","ja":"キリトの誕生日、せっかくだからあたしたちでお祝いしてあげましょうぱーっと盛大にね!"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_uw_2nd_anniv_4#originalText","id":"talk.vc.home_bd_edith_uw_2nd_anniv_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"尤吉欧生日，妳要不要主动送礼物给他？我想不管收到什么，他一定都会很高兴的。","en":"Why don't you give Eugeo a present for his birthday? I'm sure he'd love anything.","ja":"ユージオの誕生日は、あなたから贈り物をあげたら?どんなものでも、きっと喜ぶわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_uw_2nd_anniv_5#originalText","id":"talk.vc.home_bd_edith_uw_2nd_anniv_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天是一年里我最开心的日子。因为，这天是妳的生日啊，我怎么可能会不开心呢！","en":"Today is the happiest day of the year. Why? Because it's your birthday! Of course it makes me happy!","ja":"今日は一年で一番うれしい日だって、あなたの誕生日なんだものうれしいに決まってるじゃない!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_edith_uw_2nd_anniv_1#originalText","id":"talk.vc.home_etc_edith_uw_2nd_anniv_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"任务完成，辛苦了。妳这次的表现也很精彩，我可不能输给妳呢。","en":"Good work out there! You handled that excellently, as always. But I won't let you outshine me!","ja":"任務遂行、お疲れさま今回も見事なお手並みだったわあたしも負けてられないわね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_edith_uw_2nd_anniv_2#originalText","id":"talk.vc.home_etc_edith_uw_2nd_anniv_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"有人送礼给妳喔。呵呵，我倒觉得妳可以坦率地表示喜悦。","en":"You've got a gift. Aww, it's okay to smile, you know? I'm sure it's something good.","ja":"あなたに贈り物が来ているわふふ、そこは素直に喜んでいいところだと思うけど"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_edith_uw_2nd_anniv_3#originalText","id":"talk.vc.home_etc_edith_uw_2nd_anniv_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"下次的任务好像确定了呢。我也会帮妳忙的，早点解决吧！","en":"Your next assignment's arrived. Come on, let's get it done! I'll help.","ja":"次の任務、決まったみたいねあたしも手伝うから、早めに片付けちゃいましょう!"},"kind":"dialogue"},{"uid":"talk.vc.home_edith_swimsuit_wait_1#originalText","id":"talk.vc.home_edith_swimsuit_wait_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"好热呀～！想冲冲凉就把铠甲脱了！","en":"It is HOT! I want to go for a swim so I took off my armor!","ja":"暑いわね～!水浴びしたくて鎧脱いじゃった!"},"kind":"dialogue"},{"uid":"talk.vc.home_edith_swimsuit_touch_1#originalText","id":"talk.vc.home_edith_swimsuit_touch_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"什、什么啦……","en":"Wh-What?","ja":"な、なによ……"},"kind":"dialogue"},{"uid":"talk.vc.home_edith_swimsuit_touch_2#originalText","id":"talk.vc.home_edith_swimsuit_touch_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"哇啊啊！我说你这家伙，想死吗！？","en":"Hey! You gotta death wish or somethin'?","ja":"うわぁっ!ちょっとあんた、死にたいの?!"},"kind":"dialogue"},{"uid":"talk.vc.home_edith_halloween_wait_1#originalText","id":"talk.vc.home_edith_halloween_wait_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我呀～果然很适合这类的衣服呢～！","en":"These ears catch your attention? Feel free to touch them!","ja":"あたしってばこんな服も似合っちゃうのね～!"},"kind":"dialogue"},{"uid":"talk.vc.home_edith_halloween_touch_1#originalText","id":"talk.vc.home_edith_halloween_touch_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"很介意我的耳朵吗？再多触碰一些也没关系哦～","en":"These ears catch your attention? Feel free to touch them!","ja":"耳が気になる?もっと触っていいよ〜"},"kind":"dialogue"},{"uid":"talk.vc.home_edith_halloween_touch_2#originalText","id":"talk.vc.home_edith_halloween_touch_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"呵呵呵……我要来吃掉可爱的孩子啰～！嘎嗷～！","en":"Hehehe... Watch out cuties, I'll eat you up!","ja":"ふっふっふ……かわいい子は食べちゃうぞ〜!がお〜!"},"kind":"dialogue"},{"uid":"talk.vc.home_edith_uw_2022_new_year_wait_1#originalText","id":"talk.vc.home_edith_uw_2022_new_year_wait_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我来拜年了。今年也请多多指教一整年啰。","en":"Just dropping by to wish you a happy new year! Hope you have a good one!","ja":"新年のご挨拶に来たの今年も一年、よろしくね"},"kind":"dialogue"},{"uid":"talk.vc.home_edith_uw_2022_new_year_wait_2#originalText","id":"talk.vc.home_edith_uw_2022_new_year_wait_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"像是可以拉这么长而且还软软嫩嫩的东西我还是第一次吃！也要让爱丽丝吃吃看才行！","en":"MmmMmm! I've never had something this chewy before! Alice just HAS to try it!","ja":"あんなに伸びてもちもちしたもの初めて食べたわ!アリスにも食べさせてあげなくちゃ!"},"kind":"dialogue"},{"uid":"talk.vc.home_edith_uw_2022_new_year_touch_1#originalText","id":"talk.vc.home_edith_uw_2022_new_year_touch_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"怎么样，适合吗？难得穿的这么漂亮，我们出门去逛逛吧！","en":"How do I look? All dressed up with no where to go...unless you take me! Come on, let's go!","ja":"どうどう、似合ってる?せっかくこんなに綺麗にしたんだしおでかけしましょうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_wedding_1#originalText","id":"talk.vc.home_wait_edith_wedding_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这就是另一个世界的服装……「礼服」啊？真是美极了！","en":"So this is clothing from the real world... A \"dress,\" right? It's so cute!","ja":"これが向こうの世界の衣装……「ドレス」なのねとってもステキだわ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_wedding_2#originalText","id":"talk.vc.home_wait_edith_wedding_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这下子随时欢迎妳把我娶回家，然后我们就能一直在一起了！","en":"Now you'll be able to make me your wife whenever you want. Then we can always be together!","ja":"これで、いつでもあたしをお嫁さんにしていいんだからねそうすればいつも一緒!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_wedding_3#originalText","id":"talk.vc.home_wait_edith_wedding_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"如果要一起住，妳喜欢怎样的房子？我觉得还是要有一些花朵点缀才好。","en":"If we lived together, what kind of house would you like? I'd definitely want lots of flowers.","ja":"ふたりで住むとしたらどんな家がいい?やっぱり、お花は飾りたいよね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_wedding_4#originalText","id":"talk.vc.home_wait_edith_wedding_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"不知道骑士长看到我们这个样子会怎么想？说不定他会愿意祝福我们呢。","en":"What do you think the Commander'd say at the sight of us? Actually, we might get his blessing.","ja":"こんなあたしたちを見たら騎士長はどう思うかしら?案外、祝福してくれるかも"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_wedding_5#originalText","id":"talk.vc.home_wait_edith_wedding_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"妳要不要也试穿看看？虽然有点不方便行动，但会产生一种喜庆欢愉的心情喔。","en":"Why don't you try wearing it, too? Might be a bit hard to move, but it just makes me feel so stylish.","ja":"あなたも着てみたら?ちょっと動きにくいけどなんだか気分が華やかになるわ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_wedding_6#originalText","id":"talk.vc.home_wait_edith_wedding_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"一辈子只会穿这么一次的衣服居然做得如此奢华……另一个世界果然叫人吃惊呢。","en":"Wow, fancy making all these clothes I'd only get to wear once in a lifetime. The real world is so cool!","ja":"一生に一度しか着ない服をこんなに贅沢に作るなんて……やっぱり向こうの世界はすごいわ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_wedding_7#originalText","id":"talk.vc.home_wait_edith_wedding_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"怎么样？妳觉得我……看起来漂亮吗？","en":"Well? How do I look?","ja":"どう?あたし……キレイに見える?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_wedding_8#originalText","id":"talk.vc.home_wait_edith_wedding_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我有时候会想，如果能跟妳结婚，那会有多么美妙呢。","en":"Sometimes I think just how lovely it'd be if you and I got married.","ja":"もしあなたと結婚できたらそれはどんなにステキかって思うことはあるわ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_wedding_9#originalText","id":"talk.vc.home_wait_edith_wedding_9","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"好了啦，妳别光顾着害羞，好好看着我。因为我也想注视着妳啊。","en":"Come on, don't be shy! Look at me. I wanna have a look at you, too.","ja":"ほら、恥ずかしがらないでこっちを見てあたしもあなたを見たいから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_wedding_1#originalText","id":"talk.vc.home_touch_edith_wedding_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"哎唷！把我欺负得这么惨，事情就没办法轻易落幕啰？","en":"Easy, tiger! Once you cross that line, there's no turning back.","ja":"おっと!そこまでやられちゃったらもう引き返せないわよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_wedding_2#originalText","id":"talk.vc.home_touch_edith_wedding_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"妳那澄澈的蓝色瞳孔，跟我的红色瞳孔……不觉得很登对吗？","en":"Your crystal-blue eyes and my scarlet orbs. Pretty nice combo, dontcha think?","ja":"あなたの瞳の透き通るような青とあたしの紅い瞳……なかなかお似合いだと思わない?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_wedding_3#originalText","id":"talk.vc.home_touch_edith_wedding_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"妳这样要我怎么不小鹿乱撞啊？真是的……太积极了啦。","en":"Hey, don't do that unless you wanna get me worked up. Sheesh! You're just so forward.","ja":"そんな風にされたらドキドキしちゃうじゃないもう……積極的なんだから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_wedding_4#originalText","id":"talk.vc.home_touch_edith_wedding_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"妳其实很怕寂寞吗？没关系，别怕……来我这边吧。","en":"Hey, come clean, you're actually pretty needy, aren't ya? It's okay. Come to Eydis.","ja":"あなた、実は寂しがり屋なの?いいよ、ほら……こっちに来て"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_wedding_5#originalText","id":"talk.vc.home_touch_edith_wedding_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这边的构造果然很让人好奇吧？妳来看看实际上是什么样子。","en":"Yeah, I can't help but wonder how these things were built. Go have a peek, okay?","ja":"やっぱり、この辺りの構造は気になっちゃうわよねどんな風になってるか、覗いてみて"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_wedding_6#originalText","id":"talk.vc.home_touch_edith_wedding_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"对了对了，听说在另一个世界，会交换戒指当成婚姻关系的证明。我们也来试试吧？","en":"Yeah, I heard in the real world, people exchange rings when they're engaged. Maybe we should, too?","ja":"そうそう、向こうの世界では婚姻の証に指輪を交換するんだってあたしたちもやってみようか"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_wedding_7#originalText","id":"talk.vc.home_touch_edith_wedding_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天妳可以尽情地跟我撒娇喔。到了明天，就换我向妳撒娇了。","en":"It's okay. Be as needy as you want today. You'll make it up to me tomorrow.","ja":"今日は思う存分甘えていいのよ明日は、あたしがあなたに甘えるから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_wedding_8#originalText","id":"talk.vc.home_touch_edith_wedding_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"妳的手摸起来触感是如此特别，没有任何东西可以相提并论呢。","en":"The feel of your hand...it's so special. Completely unlike anything else.","ja":"あなたの手の感触他の何とも比べられない特別な感触なの"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_wedding_1#originalText","id":"talk.vc.home_time_edith_wedding_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"虽然看起来跟平时没什么不同，但这个早晨依然是特别的。因为……我的身旁有妳在啊。","en":"Everything looks the same, but today is a very special day. Why? Well...because I'm with you.","ja":"見た目はいつもと同じだけど今日は特別な朝なのだって……あなたと一緒だから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_wedding_2#originalText","id":"talk.vc.home_time_edith_wedding_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"好像流了不少汗呢，我们去洗个晨浴好了。欸，可以吧？","en":"Whew, I'm all sweaty! Let's go take a morning bath. Come on, please?","ja":"なんだか汗かいちゃったわねちょっと朝のお風呂に行こうかね、いいでしょ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_wedding_4#originalText","id":"talk.vc.home_time_edith_wedding_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"只属于两人的悠闲时光，真是奢侈呢。如果每天都能这样该有多好。","en":"I just love these lazy moments with you. I feel like a queen! Wish every day could be like this.","ja":"ふたりだけの、のんびりな時間すごく贅沢ね毎日がこうだったらいいのに"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_wedding_5#originalText","id":"talk.vc.home_time_edith_wedding_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天只有妳能跟我在一起，其他不管谁来打扰我都会撵走。","en":"Today, it's just gonna be you and me. All day. If someone comes along, I'm pushing 'em away!","ja":"今日はずっとふたりきり誰が来ても追い出しちゃうんだから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_wedding_7#originalText","id":"talk.vc.home_time_edith_wedding_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"晚上吃大餐啰！怎么说都是我跟妳两个人值得庆祝的好日子……妳说对吧？","en":"We're having a feast tonight! A celebration, really. For you and me... For us.","ja":"夜はご馳走よ!なんといってもお祝いなんだからあなたとあたし、ふたりの……ね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_wedding_8#originalText","id":"talk.vc.home_time_edith_wedding_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"穿成这样睡觉，衣服会皱掉……不过算了，就这样一起睡吧。","en":"Going to bed as I am always wrinkles my clothes...but oh well. Let's sleep together as-is!","ja":"この格好で寝ると、服が乱れちゃうけど……ま、いっかこのまま一緒に寝ちゃいましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_wedding_10#originalText","id":"talk.vc.home_time_edith_wedding_10","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"……我以为是场幸福的梦，但却不是，妳真的就在我身边。","en":"I thought I was just having a good dream...but it wasn't a dream! You really are here with me.","ja":"……幸せな夢だなって思ったら、夢じゃなかったほんとにあなたが隣にいてくれた"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_wedding_11#originalText","id":"talk.vc.home_time_edith_wedding_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"果然怎样都睡不着耶。妳就躺在人家旁边，我当然会小鹿乱撞啊。","en":"I just can't sleep! How could I? When I'm with you, my heart just won't stop racing.","ja":"やっぱり眠れないよねだって、あなたと一緒なんだもんドキドキしちゃうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_wedding_11#originalText","id":"talk.vc.home_day_edith_wedding_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"收假日总是让我忧郁，但今天感觉拿得出干劲。因为有看到妳的脸啊。","en":"Usually, I feel blah right after a vacation, but I'm energized today! Probably because I got to see you.","ja":"お休み明け、いつもは憂鬱だけど今日は頑張れそうあなたの顔を見られたからね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_wedding_12#originalText","id":"talk.vc.home_day_edith_wedding_12","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"真是的，偏偏这时候要出任务……不过，像这样与妳在一起，任务带来的疲劳也会通通消散呢。","en":"A mission? Now? What lousy timing. Good thing I have you to help soothe my angry muscles.","ja":"まったく、こんな時に任務なんて……でも、こうして一緒にいればその疲れも癒やされるってものね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_wedding_13#originalText","id":"talk.vc.home_day_edith_wedding_13","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"难得休假，要不要再一起出远门呢？我们的飞龙一定也会高兴的。","en":"Hey, since we don't have to work today, wanna go flying? It'll be good for us and the dragons!","ja":"せっかくのお休みだからまたふたりで遠乗りしない?飛竜たちもきっと喜ぶわ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_wedding_14#originalText","id":"talk.vc.home_day_edith_wedding_14","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"妳不觉得假期太早结束了吗？是不是有人调快了时间啊？","en":"Wait, isn't it too early to stop working? Did someone speed up time or something?","ja":"ちょっとお休みが終わるの早すぎじゃない?誰かが時間を早めてないかしら"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_wedding_1#originalText","id":"talk.vc.home_event_edith_wedding_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"新年快乐，今年我们也要一直在一起喔。","en":"Happy New Year! Looking forward to lots of together-time with you.","ja":"あけましておめでとう今年もずっと一緒にいようね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_wedding_2#originalText","id":"talk.vc.home_event_edith_wedding_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"冻结天命的人该吃多少颗豆子啊？就照外表年龄吃……可以吗？","en":"I'm supposed to eat as many beans as my age, but I don't age, sooo... Should I go by how old I look?","ja":"天命凍結してる人はいくつ豆を食べればいいんだろう見た目の年齢……でいいのかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_wedding_3#originalText","id":"talk.vc.home_event_edith_wedding_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"原来冬至祭典的习俗，在另一个世界是挑这个时候进行啊。不用说，我当然也有准备妳的份喔。","en":"So this is when winter solstice is celebrated in the real world. Don't worry, I've got some for you, too.","ja":"冬至祭の風習を、向こうではこの時期にやるんだね当然、あなたにも用意してあるわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_wedding_4#originalText","id":"talk.vc.home_event_edith_wedding_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"看着这个小小的娃娃，我的胸口就会没来由地为之一紧。到底是为什么呢……","en":"The sight of these tiny dolls makes me feel sentimental for some reason. I wonder why?","ja":"この小さな人形を見ているとなんとなく胸がキュッてするのどうしてだろうなあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_wedding_5#originalText","id":"talk.vc.home_event_edith_wedding_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这个回礼的习俗会害惨之前收到很多礼物的人吧？好比说，像是桐人啦……","en":"This thank-you gift custom must be a hassle for people who get a lot of candy. Like, say, Kirito...","ja":"このお返しっていう風習たくさんもらう人は大変ねたとえば、キリトとか……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_wedding_6#originalText","id":"talk.vc.home_event_edith_wedding_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"居然会设立「可以说谎的日子」，另一个世界是不是也受到禁忌束缚，生活过得喘不过气啊……","en":"People in the real world made a holiday where it's okay to lie? Do they hate their Taboo Index, too?","ja":"「嘘をついてもいい日」を作るなんて、向こうも禁忌に縛られて大変なのかしら……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_wedding_7#originalText","id":"talk.vc.home_event_edith_wedding_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我想趁这次休假去妳的故乡看看耶，那里是很棒的地方没错吧？","en":"I'd love to visit your hometown during our vacation. It sounds like it was a great place.","ja":"このお休みで、あなたの故郷に行きたいな。とてもいいところだったでしょ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_wedding_8#originalText","id":"talk.vc.home_event_edith_wedding_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"穿成这样没办法在下雨天外出呢，还是乖乖待在家里好了。","en":"Guess we can't go out in the rain dressed like this. Nothing to it. Let's just stay inside.","ja":"この格好だと、雨の中外には出られないわね大人しくお家にいましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_wedding_9#originalText","id":"talk.vc.home_event_edith_wedding_9","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"听说写下愿望就会实现耶！欸，我们要不要一起写？内容的话……嘿嘿，不告诉妳。","en":"Our prayers will be answered?! Oh, let's write ours together! What'll I pray for? Hehe. It's a secret.","ja":"願いを書くと叶うんだって!ね、ふたりで一緒に書かない?内容は……えへへ、秘密"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_wedding_10#originalText","id":"talk.vc.home_event_edith_wedding_10","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"穿成这样参加夏至祭典的话，会不会被认为是街头艺人啊？不过那样也挺有趣的就是了。","en":"If I go to the Summer Festival dressed like this, won't people think I'm an actor? Could be fun!","ja":"この格好で夏至祭に行ったら大道芸だと思われちゃうかしら?それも面白そうだけどね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_wedding_11#originalText","id":"talk.vc.home_event_edith_wedding_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天是假期最后一天，幸好有妳陪我，不然我可能会觉得灰心又忧郁。","en":"I'm glad I get to spend the last day of vacation with you. I'd be bummed if I were alone.","ja":"お休み最後の日だからあなたと一緒でよかったそうじゃなかったら挫けてたかも"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_wedding_12#originalText","id":"talk.vc.home_event_edith_wedding_12","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"妳看看天空，不觉得今天的露那利亚大人特别美吗？","en":"Ooh, look! Lunaria is looking extra beautiful tonight, dontcha think?","ja":"ほら、見て今日のルナリア様は、一段とお美しいと思わない?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_wedding_13#originalText","id":"talk.vc.home_event_edith_wedding_13","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我发了糖果给孩子们喔。发现他们比我预期的还要高兴，让我也跟着开心起来了。","en":"I gave candy to some kids. They were so happy about it that I couldn't help but crack a smile.","ja":"子どもたちにお菓子をあげたの思ったより喜んでもらえてあたしもうれしくなっちゃった"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_wedding_15#originalText","id":"talk.vc.home_event_edith_wedding_15","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"不如我们用光素术跟大树来重现看看那个叫「圣诞树」的东西吧？","en":"Wanna try recreating that Krismis- tree thing with light elements and a giant pine? Think it might work?","ja":"その「クリスマスツリー」っていうの光素術と大きな木を使って再現してみたらどうかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_wedding_3#originalText","id":"talk.vc.home_bd_edith_wedding_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天是桐人的生日，妳总该有准备礼物吧？妳不能输给其他女生喔！","en":"You did get Kirito a present for his birthday, right? You can't let the other girls upstage you!","ja":"キリトの誕生日、ちゃんと準備したんでしょうね?ダメよ、ほかの子に負けたら!"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_wedding_4#originalText","id":"talk.vc.home_bd_edith_wedding_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天是尤吉欧的生日啊。我们把桐人也找来，大家一起盛大地庆祝吧！","en":"It's Eugeo's birthday, eh? Let's invite Kirito and some others and have a big party!","ja":"ユージオの誕生日ねキリトも呼んで、みんなで盛大にお祝いしましょう!"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_wedding_5#originalText","id":"talk.vc.home_bd_edith_wedding_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"祝妳生日快乐，妳的存在就是我的幸福。我还得感谢妳的父母才行呢。","en":"Happy Birthday! My life is way, waaay happier with you in it. I need to thank your parents.","ja":"誕生日おめでとうあなたがいることが、あたしの幸せよご両親にも感謝しないとね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_wedding_6#originalText","id":"talk.vc.home_bd_edith_wedding_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天是亚丝娜大人的生日……她很擅长穿着打扮，挑饰品之类的当礼物大概不错吧？","en":"Asuna's birthday... She's a stylish lady, so maybe jewelry would be a good gift for her?","ja":"アスナ様のお誕生日……あの方はおしゃれだから、贈り物は装飾品とかいいんじゃないかしら"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_wedding_7#originalText","id":"talk.vc.home_bd_edith_wedding_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我觉得莉法的生日，在黑暗界肯定会变成很盛大的庆典。","en":"I'll bet even the Dark Realm will hold a big celebration for Leafa's birthday.","ja":"リーファさんのお誕生日はきっと暗黒界でものすごいお祭りになってると思うの"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_wedding_8#originalText","id":"talk.vc.home_bd_edith_wedding_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"比起盛大地办理，我想专找至亲好友替诗乃大人庆生，或许还比较能讨她欢心喔。","en":"Sinon would probably prefer an intimate gathering of friends over a big party.","ja":"シノン様は、盛大にやるより仲良しな人だけでお祝いしてあげる方が喜ぶかもね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_wedding_11#originalText","id":"talk.vc.home_bd_edith_wedding_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我觉得不管送什么罗妮耶都会开心……但她都留长头发了，送发饰或许不错。","en":"I figure Ronie would appreciate any gift, but maybe a ribbon for her long hair would be nice.","ja":"ロニエなら何を贈っても喜んでくれると思うけど……髪を伸ばしたから、その飾りがいいかも"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_wedding_12#originalText","id":"talk.vc.home_bd_edith_wedding_12","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天是缇洁的生日呢。罗妮耶正在准备替她庆生，所以我打算过去帮忙。","en":"So it's Tiese's birthday today. I heard Ronie was planning a party, so I'm gonna go help.","ja":"ティーゼの誕生日なのねロニエがお祝いの準備してるから手伝いに行こうと思うの"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_wedding_14#originalText","id":"talk.vc.home_bd_edith_wedding_14","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"莉兹贝特是冶炼师？这样的话，让她参观圣堂的武器库应该会很开心吧。","en":"Isn't Lisbeth a blacksmith? She'd probably love a tour of the Cathedral armory.","ja":"リズベットさんは鍛冶師なの?だったら、カセドラルの武器庫を見せてあげたら喜ぶでしょうね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_wedding_15#originalText","id":"talk.vc.home_bd_edith_wedding_15","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"西莉卡的飞龙非常可爱，所以我挑了飞龙用的饰品送她。","en":"Silica's dragon is so cute that I gave her some jewelry for it for her birthday.","ja":"シリカちゃんの飛竜すっごく可愛いから、贈り物はあの子を飾る装飾品を贈ったの"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_edith_wedding_1#originalText","id":"talk.vc.home_etc_edith_wedding_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"任务达成，辛苦妳了。今天就好好休息吧，我会替妳消除疲劳。","en":"Good work today. Snuggle up to me and I'll make sure you rest well tonight.","ja":"任務達成、お疲れさま今日はゆっくり休みましょうあたしが癒やしてあげるから"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_edith_wedding_2#originalText","id":"talk.vc.home_etc_edith_wedding_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"开礼物时总会让人兴奋不已呢。欸，我也可以在一旁看吗？","en":"Something about opening presents is just so exciting! Hey hey, can I watch?","ja":"贈り物を開けるのってなんだかワクワクするわよねね、あたしも見てていい?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_edith_wedding_3#originalText","id":"talk.vc.home_etc_edith_wedding_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"听说有新任务，难得有时间可以跟妳在一起的说。算了，抱怨也没用。","en":"A new mission just came in. Too bad, I was having so much fun hanging out with you.","ja":"新しい任務だってせっかくあなたと一緒だったのにでもまあ、しょうがないか"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_1st_1#originalText","id":"talk.vc.home_wait_edith_1st_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天天气真好呢。对了，来喂鱼给雾舞和雨缘牠们吃如何呢？","en":"What a beautiful day! Ooh, how about we feed Kirimai and Amayori some fish?","ja":"今日はいい天気ねえそうだ、霧舞と雨縁たちに魚食べさせてあげようか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_1st_2#originalText","id":"talk.vc.home_wait_edith_1st_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"集成骑士也有许多可爱的女孩子呢。当然，妳是最可爱的。","en":"The Order sure has its fair share of pretty girls. You're number one, of course.","ja":"整合騎士も可愛い女の子が多いのよねもちろん、あなたが一番だけど"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_1st_3#originalText","id":"talk.vc.home_wait_edith_1st_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"现在虽然无法实现，但将来恢复和平后，希望可以漫无目的地自由旅行呢。","en":"Someday, when we have peace, I'd love to just fly off somewhere, with no destination in mind.","ja":"今はできないけど、いつか平和になったら、目的もなく自由に旅をしてみたいな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_1st_4#originalText","id":"talk.vc.home_wait_edith_1st_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"暗之国有个很嚣张的女孩子，不晓得还能不能再遇到她啊～","en":"I once met this really annoying girl in the Dark Territory. Wonder if I'll ever see her again.","ja":"闇の国に、すっごく生意気な女の子がいたの。またどこかで会う日が来るのかなー"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_1st_9#originalText","id":"talk.vc.home_wait_edith_1st_9","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"像这样板着脸想着事情的妳，也很有魅力喔。","en":"You're really cute when you get all serious with something on your mind.","ja":"そうやって、難しい顔で考え事をしているあなたもとっても魅力的よ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_1st_1#originalText","id":"talk.vc.home_touch_edith_1st_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这个发饰很可爱吧？是我被召唤到这里后开始戴的唷。","en":"Isn't this hair ribbon cute? I've had it in my hair since the moment I was summoned.","ja":"この髪飾り、かわいいでしょこっちに喚ばれた時からついてたのよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_1st_2#originalText","id":"talk.vc.home_touch_edith_1st_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"真是纤细优雅的手指……让妳梳头发总觉得非常舒服呢。","en":"What delicate fingers... It just feels so soothing when you caress my hair.","ja":"繊細でしなやかな指……あなたに髪を梳かれるとなんだか気持ちよくなっちゃう"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_1st_4#originalText","id":"talk.vc.home_touch_edith_1st_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"穿着盔甲很容易流汗，会不自觉地想脱掉呢。","en":"Armor makes me sweat, so I always want to strip it off as soon as possible.","ja":"鎧を着てると汗をかくからつい脱ぎたくなっちゃうのよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_1st_5#originalText","id":"talk.vc.home_touch_edith_1st_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"突、突然就出手是吧？我可不会输的！看我的！","en":"M-My, how assertive you are. Well, two can play at that game! Take this!","ja":"い、いきなり攻めてくるわねあたしだって負けないから!反撃してやる!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_1st_6#originalText","id":"talk.vc.home_touch_edith_1st_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"听说啊，人在寂寞的时候会寻求温暖喔。呵呵，再靠紧一点也可以唷。","en":"People always want to cuddle when they're lonely... Hehe. It's okay, come closer.","ja":"ぬくもりがほしいのって寂しい時なんだってふふ、もっとくっついてもいいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_1st_1#originalText","id":"talk.vc.home_time_edith_1st_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"早安。哎呀，妳看起来很困呢。去洗个澡让自己清醒一下吧。","en":"Good morning. Oh, you look so sleepy. Maybe a nice bath would wake you up?","ja":"おはようあら、まだ眠そうねお風呂に入って目を覚ましましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_1st_4#originalText","id":"talk.vc.home_time_edith_1st_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"好久没有一起休假了。请人做个便当，出门去哪边走走吧。","en":"Been a while since we've had a day off together. Let's go on a picnic!","ja":"久しぶりに一緒のおやすみねお弁当作ってもらってどこかにお出かけしましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_1st_7#originalText","id":"talk.vc.home_time_edith_1st_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天啊，被我看见索鲁斯大人躲起来的瞬间了，明天肯定会有好事发生！","en":"I saw Solus pop behind a cloud to hide. That means tomorrow's sure to be auspicious!","ja":"今日はね、ソルス様が隠れる瞬間を見られたの明日はきっといいことがあるわ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_1st_10#originalText","id":"talk.vc.home_time_edith_1st_10","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"真是宁静的夜晚呢。这么安静反而会让人清醒过来。","en":"What a quiet night. It's actually the still nights that keep me awake.","ja":"静かな夜ねこんなに静かだと、逆に目が覚めちゃうんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_1st_1#originalText","id":"talk.vc.home_day_edith_1st_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"天界每天都是安息日吗？那样的话，应该很无聊吧。","en":"I wonder if every day is a Day of Rest in Heaven? Hope not. That would get pretty boring.","ja":"天界は、毎日が安息日なのかなだとしたら、そのうち退屈しちゃいそうね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_1st_2#originalText","id":"talk.vc.home_day_edith_1st_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"妳也差不多累了吧？这时候去泡个澡是最棒的！","en":"You must be getting tired. You know the best remedy for that? Taking a bath with me!","ja":"そろそろ疲れが溜まってくる頃よね。そんな時はお風呂に入るのが一番よ!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_1st_3#originalText","id":"talk.vc.home_day_edith_1st_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"每次休假啊，一开始都想说要做这个做那个，但结果总是不知不觉混了一天呢。","en":"On Days of Rest, I always make a lot of plans...then wind up just slacking off.","ja":"お休みの日って、最初はいろいろやろうと思っても、ついついダラッとしちゃうのよね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_1st_4#originalText","id":"talk.vc.home_day_edith_1st_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"休假的夜晚会让人感到有点寂寞呢。","en":"The night after a Day of Rest is always a little glum.","ja":"お休みの日の夜は少し寂しい気分になるわ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_edith_1st_1#originalText","id":"talk.vc.home_season_edith_1st_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"一到春天，就想到又过一年了啊。不过集成骑士没有天命，所以没什么关系呢。","en":"Another spring, another year gone by. Not that it matters when you're immortal like us.","ja":"春になると、また一年過ぎちゃったって思うのよ。整合騎士には天命がないから関係ないのにね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_edith_1st_2#originalText","id":"talk.vc.home_season_edith_1st_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"夏天就是要冲凉呢。来，一起洗吧。没什么好害羞的吧。","en":"Summer is all about swimming. Come take a dip with me! It's okay, don't be shy.","ja":"夏は水浴びに限るわねほら、一緒に入りましょう恥ずかしがることは無いでしょ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_edith_1st_3#originalText","id":"talk.vc.home_season_edith_1st_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"看见结成金黄色的麦穗，就会不由得开心起来。因为这样大家就能过冬了。","en":"Seeing the wheat turn gold makes me so happy, knowing we'll have a comfortable winter.","ja":"麦の穂が金色に実ってるのを見ると、うれしくなっちゃうのこれでみんな、冬を越せるんだって"},"kind":"dialogue"},{"uid":"talk.vc.home_season_edith_1st_4#originalText","id":"talk.vc.home_season_edith_1st_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"虽然我喜欢赏雪，但在下雪的空中飞可就不行了，太冻了，脸会很痛。","en":"I love watching it snow, but it's impossible to fly in. Too much brain freeze.","ja":"雪を見るのは好きだけどその中を飛ぶのは無理ね寒すぎて顔が痛いの"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_sleeping_1#originalText","id":"talk.vc.home_wait_edith_sleeping_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"欸，你再靠过来一点。有什么关系嘛，就现在而已啊。","en":"Heyyy, come here for bit? Aw, come on.","ja":"ねえ、もうちょっとこっちに来ていいじゃない、今くらい"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_sleeping_2#originalText","id":"talk.vc.home_wait_edith_sleeping_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"人的体温竟然会让人如此安心呢。呵呵，感觉会上瘾。","en":"I didn't realize just how comforting body heat could be. Hehe, I could get used to this.","ja":"人のぬくもりってこんなに安心するのねふふ、癖になりそう"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_sleeping_3#originalText","id":"talk.vc.home_wait_edith_sleeping_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"像这样什么事都不做，就只是待在彼此身边……真是奢侈的时光呢。","en":"Not doing anything and just... being...together. It's the most luxurious way to spend time.","ja":"こうやって、何にもしないでただ一緒にいる……最高に贅沢な時間ね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_sleeping_4#originalText","id":"talk.vc.home_wait_edith_sleeping_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"现在的话，声音再小一点也没关系的。……欸，你听得见吧？","en":"It's okay. You can be a little quieter. See? Can't you hear it?","ja":"今なら、もっと声が小さくても大丈夫……ね、聞こえるでしょ?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_sleeping_5#originalText","id":"talk.vc.home_wait_edith_sleeping_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"即使这么近看，你还是一样很可爱耶。光是能像这样看着你就好幸福。","en":"Even up close, you're still so adorable. Fills me with joy just watching you.","ja":"間近で見ても、やっぱりあなたはかわいいわこうして見てるだけで幸せ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_sleeping_6#originalText","id":"talk.vc.home_wait_edith_sleeping_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"头发长的话，睡觉时会有点困扰呢。你平常都怎么处理呢？","en":"Sleeping with long hair is a bit of a pain. How do you handle it?","ja":"髪が長いと、寝る時は少し大変よねあなたは、いつもどうしてるの?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_sleeping_7#originalText","id":"talk.vc.home_wait_edith_sleeping_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"明天的事就别想了啦。今天，我与你在一起，现在我想好好品味这段时光。","en":"Oh, who cares about tomorrow? Today, it's just you and me. I want to savor this moment.","ja":"明日のことはいいじゃない今日あなたと一緒にいる今はその時間を味わいたいの"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_sleeping_8#originalText","id":"talk.vc.home_wait_edith_sleeping_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天的事情我一定永远都不会忘记。","en":"I doubt I'll ever forget this day.","ja":"今日のことは、きっとずっと忘れないわ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_sleeping_9#originalText","id":"talk.vc.home_wait_edith_sleeping_9","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"……睡着了吗？呵呵，睡脸也好可爱喔。","en":"Did you...fall asleep on me? Hehe. You're so cute when you're asleep.","ja":"……寝ちゃったの?ふふ、寝顔もかわいいな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_sleeping_1#originalText","id":"talk.vc.home_touch_edith_sleeping_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"……跟平常反过来了呢。不过，我也很喜欢你摸我的头发喔。","en":"This is the reverse of what usually happens... But I love having you touch my hair.","ja":"……これじゃいつもと反対ねでも、あなたに髪を触られるの大好きよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_sleeping_2#originalText","id":"talk.vc.home_touch_edith_sleeping_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我还算喜欢自己的发色啦……但我最喜欢的还是你的发色。","en":"I rather like my hair color... But I still think yours is the prettiest.","ja":"自分の髪の色も、まあ割と好きなんだけど……やっぱりあなたの髪の色が一番好き"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_sleeping_3#originalText","id":"talk.vc.home_touch_edith_sleeping_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"……我还没睡着唷。在你睡着之前，我都会醒着的。","en":"I'm not asleep yet. Don't worry. I'll stay up until you fall asleep.","ja":"……まだ寝てないわよあなたが眠るまであたしは起きてるから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_sleeping_4#originalText","id":"talk.vc.home_touch_edith_sleeping_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"做恶梦了吗？不怕不怕，姐姐我来给你一个拥抱。","en":"Did you have a bad dream? Aww, there, there. Let me hug away all your fears.","ja":"怖い夢でも見たの?よしよし、おねーさんが抱っこしてあげる"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_sleeping_5#originalText","id":"talk.vc.home_touch_edith_sleeping_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"……你听见我紧张的心跳声了吗？","en":"My heart is racing right now... Do you hear it?","ja":"……あたしのドキドキ聞こえちゃってる?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_sleeping_6#originalText","id":"talk.vc.home_touch_edith_sleeping_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"只要被你触碰，我的全身就会从那个部位开始暖起来呢。","en":"Whenever you touch me, I feel so warm and fuzzy inside.","ja":"あなたに触られるとそこからじーんと温かくなっていくの"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_sleeping_7#originalText","id":"talk.vc.home_touch_edith_sleeping_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"讨厌，会痒啦！但是……你不停手……也没关系唷。","en":"Eek, that tickles! But...don't stop, okay?","ja":"やだ、くすぐったい!でも……やめなくても、いいよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_sleeping_8#originalText","id":"talk.vc.home_touch_edith_sleeping_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"把手伸出来……今天就这样牵着手一起入睡吧。","en":"Give me your hand... Can we fall asleep holding hands like this tonight?","ja":"手を出して……こうやって繋いだまま今日は一緒に眠りましょう?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_sleeping_1#originalText","id":"talk.vc.home_time_edith_sleeping_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"……早安，昨晚睡得还好吗？","en":"Good morning... Did you sleep well?","ja":"……おはよきのうは、よく眠れた?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_sleeping_2#originalText","id":"talk.vc.home_time_edith_sleeping_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"一早就能看见你的脸，我觉得今天一整天都会很有精神！","en":"Seeing your cute face first thing in the morning gives me the energy to take on the day!","ja":"朝からあなたの顔が見られて今日は一日、元気にやれそう!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_sleeping_3#originalText","id":"talk.vc.home_time_edith_sleeping_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我说……就继续这样一下子可以吗？好不好？就再一下下。","en":"Come on, can't we stay like this just a bit longer? Please? Just a li'l bit longer, I promise.","ja":"ねえ、もう少しこのままでもいいじゃない?ね、もう少しだけ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_sleeping_4#originalText","id":"talk.vc.home_time_edith_sleeping_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"不知不觉居然已经这么晚了……每次与你相处，时间总是眨眼间就过了。","en":"I don't know how it happened, but...when I'm with you, I seem to lose track of time.","ja":"いつの間にかこんな時間……あなたといると、時間があっという間に過ぎちゃうわ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_sleeping_5#originalText","id":"talk.vc.home_time_edith_sleeping_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"肚子真的饿了呢。可是，被窝的魔力让我离不开……","en":"It's no wonder you're hungry. But the bed's magic powers are restraining me...","ja":"さすがにお腹が空いちゃったねでも、お布団の魔力があたしを引き留めるの"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_sleeping_6#originalText","id":"talk.vc.home_time_edith_sleeping_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"呼啊……一直躺着就又开始想睡了。","en":"Ahhh... All that lying down has made me sleepy again.","ja":"ふわあ～……ずっと横になってたらまた眠くなってきちゃった"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_sleeping_7#originalText","id":"talk.vc.home_time_edith_sleeping_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"虽然时间还有点早，要不要直接睡觉算了？","en":"It's still a bit early, but wanna just turn in?","ja":"まだちょっと早いけどこのまま寝ちゃおうか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_sleeping_8#originalText","id":"talk.vc.home_time_edith_sleeping_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"像这样躺着与你聊天……是我感到最开心的时光。","en":"Lying in bed and talking to you like this is my favorite part of the day.","ja":"こうやって横になってあなたとおしゃべりしてるこの時間が、一番楽しいわ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_sleeping_9#originalText","id":"talk.vc.home_time_edith_sleeping_9","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"不受任何人打扰的空间……要是每天都能像这样一起睡觉就好了。","en":"I wish we could be in our own little world, sleeping together like this undisturbed every night.","ja":"誰にも邪魔されない空間……毎日こうやって、一緒に寝られたらいいのにね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_sleeping_10#originalText","id":"talk.vc.home_time_edith_sleeping_10","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"……你醒了？其实我也是。呵呵，真巧呢。","en":"Can't sleep? Me too, actually. But I'm glad. Hehe.","ja":"……目が覚めちゃった?実は、あたしもなのふふ、奇遇だね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_sleeping_11#originalText","id":"talk.vc.home_time_edith_sleeping_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"其实我该上床睡觉了，可是我好舍不得结束与你相处的时光……","en":"I know I should get some sleep, but I don't want to waste a moment together with you.","ja":"眠らないといけないんだけどねでも、あなたとの時間がもったいなくて……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_sleeping_12#originalText","id":"talk.vc.home_time_edith_sleeping_12","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"……欸，再靠过来一点。对，更靠近一点……紧靠在我身边。","en":"Hey...come closer. Yes, closer... Snuggle right up against me.","ja":"……ねえ、もっとこっちに来てそう、もっと近く……あたしにピッタリ、くっついて"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_sleeping_1#originalText","id":"talk.vc.home_day_edith_sleeping_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"休息时间结束了……真没办法，要加油啰！况且也像这样从你身上获得了元气嘛！","en":"Aw, our day off is over... Oh well, back to the grind! Thanks for recharging me.","ja":"お休み終わっちゃった……しょうがない、頑張るか!こうやって元気もらえたしね!"},"kind":"dialogue"}]};
